-- Generated by lib/map-zones.ts (#66). Read-only world squares PoC; additive.
CREATE TABLE IF NOT EXISTS world_squares (
 x INTEGER NOT NULL, y INTEGER NOT NULL,
 zone TEXT COLLATE "C" NOT NULL CHECK(zone IN ('heartland','frontier','wildlands','commons')),
 owner TEXT COLLATE "C", terrain TEXT COLLATE "C" NOT NULL, resource TEXT COLLATE "C", feature TEXT COLLATE "C",
 PRIMARY KEY (x, y)
);
